// Navbar.jsx - исправленная версия
import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Navbar = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const { user, logout, cart, favorites } = useAuth();
  const navigate = useNavigate();

  const handleSearch = (e) => {
    e.preventDefault();
    if (searchTerm.trim()) {
      navigate(`/catalog?search=${searchTerm}`);
      setSearchTerm('');
      setIsMobileMenuOpen(false);
    }
  };

  const goToProfileTab = (tab) => {
    if (user) {
      if (tab === 'profile') {
        navigate('/profile');
      } else {
        navigate(`/profile?tab=${tab}`);
      }
    } else {
      navigate('/login');
    }
    setIsMobileMenuOpen(false);
  };

  const handleLogout = () => {
    logout();
    navigate('/');
    setIsMobileMenuOpen(false);
  };

  // Подсчёт количества товаров в корзине
  const cartItemsCount = cart ? cart.reduce((count, item) => count + (item.quantity || 1), 0) : 0;

  // Количество избранных товаров
  const favoritesCount = favorites ? favorites.length : 0;

  return (
    <nav className="bg-white shadow-lg border-b sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16">
          {/* Logo */}
          <Link to="/" className="flex items-center flex-shrink-0">
            <img 
              src="/images/logo.png" 
              alt="LUNA AUREA" 
              className="h-8 w-auto"
              onError={(e) => {
                e.target.onerror = null;
                e.target.src = "https://via.placeholder.com/150x40?text=LUNA+AUREA";
              }}
            />
            <span className="ml-2 text-xl font-serif font-bold hidden sm:block">LUNA AUREA</span>
          </Link>

          {/* Desktop Navigation Links */}
          <div className="hidden md:flex space-x-8">
            <Link to="/catalog" className="text-gray-700 hover:text-gold-600 transition-colors">КАТАЛОГ</Link>
            <Link to="/collections" className="text-gray-700 hover:text-gold-600 transition-colors">КОЛЛЕКЦИИ</Link>
            <Link to="/about" className="text-gray-700 hover:text-gold-600 transition-colors">О НАС</Link>
            <Link to="/contacts" className="text-gray-700 hover:text-gold-600 transition-colors">КОНТАКТЫ</Link>
          </div>

          {/* Icons */}
          <div className="flex items-center space-x-2 sm:space-x-4">
            {/* Search - скрываем на очень маленьких экранах */}
            <form onSubmit={handleSearch} className="relative hidden xs:block">
              <input
                type="text"
                placeholder="Поиск..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-3 pr-10 py-1.5 border rounded-full text-sm focus:outline-none focus:ring-2 focus:ring-gold-500 w-32 sm:w-40 lg:w-48"
              />
              <button 
                type="submit" 
                className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-500 hover:text-gold-600"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path>
                </svg>
              </button>
            </form>

            {/* Mobile menu button */}
            <button
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
              className="md:hidden p-2 rounded-md text-gray-700 hover:text-gold-600 hover:bg-gray-100 focus:outline-none focus:ring-2 focus:ring-inset focus:ring-gold-500"
              aria-label="Toggle menu"
            >
              <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                {isMobileMenuOpen ? (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                ) : (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
                )}
              </svg>
            </button>

            {/* Desktop Icons */}
            <div className="hidden md:flex items-center space-x-1">
              {/* Search Icon for Desktop (hidden on mobile) */}
              <button 
                onClick={() => document.querySelector('input[type="text"]').focus()}
                className="p-2 hover:bg-gray-100 rounded-full transition-colors text-gray-600 hover:text-gold-600"
                title="Поиск"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path>
                </svg>
              </button>

              {/* Profile */}
              {user ? (
                <div className="relative group">
                  <button 
                    className="p-2 hover:bg-gray-100 rounded-full transition-colors text-gray-600 hover:text-gold-600"
                    title="Профиль"
                  >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"></path>
                    </svg>
                  </button>
                  <div className="absolute right-0 mt-2 w-48 bg-white rounded-md shadow-lg py-1 z-50 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200 border">
                    <button
                      onClick={() => navigate('/profile')}
                      className="block w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 hover:text-gold-600"
                    >
                      Мой профиль
                    </button>
                    <button
                      onClick={() => navigate('/profile?tab=orders')}
                      className="block w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 hover:text-gold-600"
                    >
                      Мои заказы
                    </button>
                    <div className="border-t my-1"></div>
                    <button
                      onClick={handleLogout}
                      className="block w-full text-left px-4 py-2 text-sm text-red-600 hover:bg-gray-100"
                    >
                      Выйти
                    </button>
                  </div>
                </div>
              ) : (
                <Link 
                  to="/login" 
                  className="p-2 hover:bg-gray-100 rounded-full transition-colors text-gray-600 hover:text-gold-600"
                  title="Войти"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h7a3 3 0 013 3v1"></path>
                  </svg>
                </Link>
              )}

              {/* Favorites */}
              <button 
                onClick={() => goToProfileTab('favorites')}
                className="p-2 hover:bg-gray-100 rounded-full transition-colors text-gray-600 hover:text-gold-600 relative"
                title="Избранное"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z"></path>
                </svg>
                {favoritesCount > 0 && (
                  <span className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-4 h-4 text-xs flex items-center justify-center">
                    {favoritesCount}
                  </span>
                )}
              </button>

              {/* Cart */}
              <button 
                onClick={() => goToProfileTab('cart')}
                className="p-2 hover:bg-gray-100 rounded-full transition-colors text-gray-600 hover:text-gold-600 relative"
                title="Корзина"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z"></path>
                </svg>
                {cartItemsCount > 0 && (
                  <span className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-4 h-4 text-xs flex items-center justify-center">
                    {cartItemsCount}
                  </span>
                )}
              </button>
            </div>
          </div>
        </div>

        {/* Mobile Menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden absolute left-0 right-0 top-16 bg-white border-b shadow-lg z-40">
            <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3">
              {/* Mobile Search */}
              <form onSubmit={handleSearch} className="px-3 pb-3">
                <div className="relative">
                  <input
                    type="text"
                    placeholder="Поиск..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-gold-500"
                  />
                  <button 
                    type="submit" 
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-500"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path>
                    </svg>
                  </button>
                </div>
              </form>

              <Link
                to="/catalog"
                className="block px-3 py-3 text-gray-700 hover:text-gold-600 hover:bg-gray-50 rounded-md border-b"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                КАТАЛОГ
              </Link>
              <Link
                to="/collections"
                className="block px-3 py-3 text-gray-700 hover:text-gold-600 hover:bg-gray-50 rounded-md border-b"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                КОЛЛЕКЦИИ
              </Link>
              <Link
                to="/about"
                className="block px-3 py-3 text-gray-700 hover:text-gold-600 hover:bg-gray-50 rounded-md border-b"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                О НАС
              </Link>
              <Link
                to="/contacts"
                className="block px-3 py-3 text-gray-700 hover:text-gold-600 hover:bg-gray-50 rounded-md border-b"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                КОНТАКТЫ
              </Link>

              {/* Mobile Auth Actions */}
              <div className="pt-4 pb-3 border-t border-gray-200">
                <div className="flex items-center justify-between px-3">
                  {user ? (
                    <>
                      <div className="flex items-center space-x-4">
                        <div className="text-sm">
                          <p className="font-medium">Привет, {user.username || user.email}</p>
                          <p className="text-gray-500 text-xs">{user.email}</p>
                        </div>
                      </div>
                      <div className="flex items-center space-x-3">
                        <button 
                          onClick={() => goToProfileTab('favorites')}
                          className="p-2 hover:bg-gray-100 rounded-full relative"
                          title="Избранное"
                        >
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z"></path>
                          </svg>
                          {favoritesCount > 0 && (
                            <span className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-4 h-4 text-xs flex items-center justify-center">
                              {favoritesCount}
                            </span>
                          )}
                        </button>
                        <button 
                          onClick={() => goToProfileTab('cart')}
                          className="p-2 hover:bg-gray-100 rounded-full relative"
                          title="Корзина"
                        >
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z"></path>
                          </svg>
                          {cartItemsCount > 0 && (
                            <span className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-4 h-4 text-xs flex items-center justify-center">
                              {cartItemsCount}
                            </span>
                          )}
                        </button>
                        <button
                          onClick={handleLogout}
                          className="text-sm text-red-600 hover:text-red-800 px-3 py-1 border border-red-600 hover:bg-red-50 rounded"
                        >
                          Выйти
                        </button>
                      </div>
                    </>
                  ) : (
                    <>
                      <div className="text-sm">
                        <p className="text-gray-600">Войдите, чтобы управлять профилем</p>
                      </div>
                      <div className="flex items-center space-x-3">
                        <Link
                          to="/login"
                          className="text-gold-600 hover:text-gold-700 font-medium px-3 py-1 border border-gold-600 rounded"
                          onClick={() => setIsMobileMenuOpen(false)}
                        >
                          Войти
                        </Link>
                        <Link
                          to="/register"
                          className="bg-gold-600 hover:bg-gold-700 text-white px-3 py-1 rounded"
                          onClick={() => setIsMobileMenuOpen(false)}
                        >
                          Регистрация
                        </Link>
                      </div>
                    </>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </nav>
  );
};

export default Navbar;
